/// <summary>
/// This class is the contract for the Picklist registration pending process.
/// </summary>
[DataContract]
class METDallasPicklistRegPendingProcessContract
{
    int         tasksNumber;
    str         packedQuery;
    container   conPicklistPendingRecIds;

}

Method.Source:
/// <summary>
/// This method takes task numbers as input from UI and provides the same as output if exists
/// </summary>
/// <param name = "_tasksNumber">TaskNumber</param>
/// <returns>TaskNumber</returns>
[
    DataMember,
    SysOperationLabel('@MET:CustCreditLimitTasks'),
    SysOperationDisplayOrder('1')
]
public int parmParallelTasksNumber(int _tasksNumber = tasksNumber)
{
    tasksNumber = _tasksNumber;
    return tasksNumber;
}

/// <summary>
/// Gets/set packed query.
/// </summary>
/// <param name = "_packedQuery">Packed query.</param>
/// <returns>Packed query.</returns>
[
    DataMember,
    AifQueryType('_packedQuery', queryStr(METDallasPicklistRegPendingProcess))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// This is a parm method
/// </summary>
/// <param name = "_conOrdTrans">OrdTrans</param>
/// <returns>Container</returns>
[DataMember, SysOperationControlVisibility(false)]
public container conPicklistPendingRecords(container _conPicklistPendingRecIds = conPicklistPendingRecIds)
{
    conPicklistPendingRecIds = _conPicklistPendingRecIds;
    return conPicklistPendingRecIds;
}

/// <summary>
/// Method to get query object from packedQuery
/// </summary>
/// <returns><c>Query</c> object from packedQuery</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}
